import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("plain sword for a 1-year customer → 100 base + 10 first insurance + 5 fee = 115 G");
    it.todo("plain amulet → 60 base + 6 first insurance + 5 fee = 71 G");
    it.todo("plain staff → 80 base + 8 first insurance + 5 fee = 93 G");
    it.todo("plain potion → 40 base + 4 first insurance + 5 fee = 49 G");
  });

  describe("quote — components and building blocks", () => {
    it.todo("2 runes → 50 G base premium (premium 50 + 5 + 5 = 60 G)");
    it.todo("3 runes → 60 G base premium, block applies (premium 60 + 6 + 5 = 71 G)");
    it.todo("4 runes → 100 G base premium, no block (premium 100 + 10 + 5 = 115 G)");
    it.todo("7 runes → 175 G base premium (premium 175 + 17.5 + 5 = 197.5 → 198 G)");
    it.todo("2 runes + 1 moonstone → 75 G base premium, no block across types (premium 75 + 7.5 + 5 = 87.5 → 88 G)");
    it.todo("3 runes + 3 moonstones → 120 G base premium, two separate blocks (premium 120 + 12 + 5 = 137 G)");
  });

  describe("quote — premium modifiers", () => {
    it.todo("newcomer with a cursed steel sword, enchantment 3 → 165 G");
    it.todo("sword with enchantment 4 (not cursed) → no high-enchantment surcharge → 115 G");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies → 100 + 30 + 10 + 5 = 145 G");
    it.todo("cursed sword with enchantment 5 → both surcharges → 100 + 50 + 30 + 10 + 5 = 195 G");
    it.todo("customer with exactly 2 years → loyalty discount applies → 100 − 20 + 10 + 5 = 95 G");
    it.todo("cursed surcharge applies only to the cursed item: cursed sword + plain amulet → 160 + 50 + 16 + 5 = 231 G");
    it.todo("follow-up contract gets 15 % discount: second quote of a plain sword for a 0-year customer → 100 + 10 − 15 + 5 = 100 G");
    it.todo("long-standing customer's second contract, cursed sword enchantment 7 → 160 G (first insurance still applies)");
    it.todo("premium fractions are rounded up in MHPCO's favor (7 runes → 198 G)");
  });

  describe("claim — reimbursement", () => {
    it.todo("regular steel sword, enchantment 3, damage 500 → payout 400, remainingCap 1600");
    it.todo("rune (no enchantment/material), damage 200 → payout 100");
    it.todo("steel sword, enchantment 9, damage 1000 → payout 400 (50 % then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 → payout 400 (50 % rule wins)");
    it.todo("dragon-material sword, enchantment 5, damage 800 → payout 700");
    it.todo("dragon-material sword, exactly enchantment 8, damage 1000 → payout 400");
    it.todo("deductible applies per damaged item: sword 500 + amulet 300 → payout 600");
    it.todo("payout fractions are rounded down in MHPCO's favor (enchantment 9, damage 901 → 450.5 − 100 = 350.5 → 350)");
    it.todo("damage below deductible yields payout 0, not negative");
  });

  describe("claim — cap", () => {
    it.todo("policy with sword + amulet → cap 3200 G (remainingCap after 0-payout claim is 3200)");
    it.todo("cursed sword cap is based on unmodified insurance value → cap 2000 G");
    it.todo("sword + 3 runes block → insurance sum 1750, cap 3500 G");
    it.todo("two swords → insurance sum 2000, cap 4000; damaging both treats each with its own deductible");
    it.todo("two successive 1500 G claims on a sword → payouts 1400 (remaining 600) then 600 (remaining 0)");
    it.todo("claims on different policies have independent caps");
  });

  describe("errors", () => {
    it.todo("quote with an unknown item type (broomstick) throws");
    it.todo("claim for an item not part of the policy (amulet when only a sword insured) throws");
    it.todo("claim with an unknown item type throws");
    it.todo("claim with more damage entries of a type than insured items throws");
    it.todo("claim with a negative damage amount throws");
  });

  describe("full scenario", () => {
    it.todo("schema example: 5-year customer quotes silver amulet then claims 200 fire damage → [{premium: 59}, {payout: 100, remainingCap: 1100}]");
  });
});

