export type Item = { type: string };
export type QuoteStep = { op: "quote"; items: Item[] };
export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};
export type ScenarioResult = { results: { premium: number }[] };

const PROCESSING_FEE = 5;
const SWORD_BASE_PREMIUM = 100;
const FIRST_INSURANCE_SURCHARGE = 0.1;

export const runScenario = (scenario: Scenario): ScenarioResult => {
  return {
    results: scenario.steps.map((step) => {
      const base = step.items.length * SWORD_BASE_PREMIUM;
      return { premium: base + base * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE };
    }),
  };
};

