export type Item = { type: string };
export type QuoteStep = { op: "quote"; items: Item[] };
export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};
export type ScenarioResult = { results: { premium: number }[] };

const PROCESSING_FEE = 5;
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / 100;

const sumBasePremiums = (items: Item[]): number => {
  const runeCount = items.filter((item) => item.type === "rune").length;
  if (runeCount === BLOCK_SIZE) return BLOCK_PREMIUM;
  return items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
};

const quotePremium = (items: Item[]): number => {
  const basePremium = sumBasePremiums(items);
  const firstInsuranceSurcharge = percentOf(
    basePremium,
    FIRST_INSURANCE_SURCHARGE_PERCENT,
  );
  return Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
});

