const DEDUCTIBLE = 100;

const CAP_MULTIPLIER = 2;
const REDUCED_REIMBURSEMENT_ENCHANTMENT = 8;
const REDUCED_REIMBURSEMENT_PERCENT = 50;

const reimbursableAmount = (damage: Damage, item: Item | undefined): number =>
  (item?.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT
    ? percentOf(damage.amount, REDUCED_REIMBURSEMENT_PERCENT)
    : damage.amount;

const insuredItemFor = (damage: Damage, policyItems: Item[]): Item | undefined =>
  policyItems.find((item) => item.type === damage.itemType);

const damagePayout = (damage: Damage, policyItems: Item[]): number =>
  Math.max(0, reimbursableAmount(damage, insuredItemFor(damage, policyItems)) - DEDUCTIBLE);

const coverageCap = (policyItems: Item[]): number =>
  CAP_MULTIPLIER * policyItems.reduce((sum, item) => sum + insuranceValueOf(item.type), 0);

const processClaim = (step: ClaimStep, policyItems: Item[]): ClaimResult => {
  const payout = Math.floor(
    step.incident.damages.reduce((sum, damage) => sum + damagePayout(damage, policyItems), 0),
  );
  return { payout, remainingCap: coverageCap(policyItems) - payout };
};

const policyItemsOf = (scenario: Scenario, claim: ClaimStep): Item[] =>
  (scenario.steps[claim.policy] as QuoteStep).items;

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step, index) => {
    if (step.op === "claim") return processClaim(step, policyItemsOf(scenario, step));
    return {
      premium: quotePremium(step.items, scenario.customer.yearsWithMHPCO, index > 0),
    };
  }),
});

